import base64
import html
import io
import json
import os
from datetime import datetime

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

DATA_PATH = '/app/benchmark/data.csv'
BRIEF_PATH = '/app/benchmark/source_brief.md'
SPEC_PATH = '/app/benchmark/task_input.json'
OUT_PATH = '/app/output/final_report.html'

os.makedirs('/app/output', exist_ok=True)

with open(SPEC_PATH) as f:
    spec = json.load(f)

df = pd.read_csv(DATA_PATH)
for c in ['timestamp', 'arrival_time', 'charging_start_time', 'charging_end_time']:
    df[c] = pd.to_datetime(df[c], format='%m/%d/%Y %H:%M')

time_order = [x for x in ['Off-Peak', 'Mid-Peak', 'Peak'] if x in set(df['time_slot'])]
loc_order = [x for x in ['Urban', 'Highway', 'Suburban'] if x in set(df['location_type'])]
weather_order = sorted(df['weather_condition'].unique())
dow_order = [d for d in ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] if d in set(df['day_of_week'])]
vehicle_order = sorted(df['vehicle_type'].unique())

palette = {
    'navy': '#12324a',
    'blue': '#1f77b4',
    'sky': '#42a5f5',
    'green': '#15a66a',
    'orange': '#f59e0b',
    'red': '#d94841',
    'gray': '#6b7280',
    'light': '#f5f7fb',
    'ink': '#172033',
}

plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'axes.titlesize': 13,
    'axes.labelsize': 10,
    'xtick.labelsize': 9,
    'ytick.labelsize': 9,
    'figure.facecolor': 'white',
    'axes.facecolor': 'white',
})

def fmt(value, decimals=1, suffix=''):
    if pd.isna(value):
        return 'n/a'
    if abs(value) >= 1000 and decimals == 0:
        return f'{value:,.0f}{suffix}'
    return f'{value:,.{decimals}f}{suffix}'

def pct(value, decimals=1):
    if pd.isna(value):
        return 'n/a'
    return f'{value*100:.{decimals}f}%'

def svg_from_fig(fig):
    buf = io.StringIO()
    fig.savefig(buf, format='svg', bbox_inches='tight')
    plt.close(fig)
    svg = buf.getvalue()
    start = svg.find('<svg')
    return svg[start:]

def heatmap_svg(pivot, title, cbar_label, cmap='YlOrRd', fmt_text='.1f'):
    fig, ax = plt.subplots(figsize=(7.4, 3.3))
    data = pivot.values.astype(float)
    im = ax.imshow(data, cmap=cmap, aspect='auto')
    ax.set_xticks(np.arange(len(pivot.columns)), labels=pivot.columns)
    ax.set_yticks(np.arange(len(pivot.index)), labels=pivot.index)
    ax.set_title(title, loc='left', fontweight='bold', color=palette['ink'])
    ax.tick_params(length=0)
    for spine in ax.spines.values():
        spine.set_visible(False)
    threshold = np.nanmean(data)
    for i in range(data.shape[0]):
        for j in range(data.shape[1]):
            val = data[i, j]
            color = 'white' if val > threshold else '#172033'
            ax.text(j, i, format(val, fmt_text), ha='center', va='center', color=color, fontweight='bold')
    cbar = fig.colorbar(im, ax=ax, fraction=0.046, pad=0.04)
    cbar.ax.set_ylabel(cbar_label, rotation=270, labelpad=14)
    fig.tight_layout()
    return svg_from_fig(fig)

def grouped_bar_svg(data, title, ylabel, colors=None):
    fig, ax = plt.subplots(figsize=(7.4, 3.6))
    data.plot(kind='bar', ax=ax, color=colors or [palette['sky'], palette['orange'], palette['green']], width=0.72)
    ax.set_title(title, loc='left', fontweight='bold', color=palette['ink'])
    ax.set_ylabel(ylabel)
    ax.set_xlabel('')
    ax.grid(axis='y', alpha=.25)
    ax.legend(frameon=False, loc='best')
    for spine in ['top','right','left']:
        ax.spines[spine].set_visible(False)
    fig.tight_layout()
    return svg_from_fig(fig)

def horizontal_bar_svg(series, title, xlabel, color=palette['blue']):
    fig, ax = plt.subplots(figsize=(7.4, 4.1))
    series = series.sort_values(ascending=True)
    bars = ax.barh(series.index.astype(str), series.values, color=color)
    ax.set_title(title, loc='left', fontweight='bold', color=palette['ink'])
    ax.set_xlabel(xlabel)
    ax.grid(axis='x', alpha=.25)
    for spine in ['top','right','left']:
        ax.spines[spine].set_visible(False)
    ax.tick_params(axis='y', length=0)
    for bar in bars:
        width = bar.get_width()
        ax.text(width, bar.get_y()+bar.get_height()/2, f' {width:.1f}', va='center', fontsize=8)
    fig.tight_layout()
    return svg_from_fig(fig)

def scatter_svg(x, y, c, title, xlabel, ylabel):
    fig, ax = plt.subplots(figsize=(7.4, 3.8))
    sc = ax.scatter(x, y, c=c, cmap='viridis', s=18, alpha=.55, edgecolors='none')
    coef = np.polyfit(x, y, 1)
    xs = np.linspace(np.nanmin(x), np.nanmax(x), 100)
    ax.plot(xs, coef[0]*xs + coef[1], color=palette['red'], linewidth=2, label='linear fit')
    ax.set_title(title, loc='left', fontweight='bold', color=palette['ink'])
    ax.set_xlabel(xlabel)
    ax.set_ylabel(ylabel)
    ax.grid(alpha=.22)
    ax.legend(frameon=False)
    cbar = fig.colorbar(sc, ax=ax, fraction=0.046, pad=0.04)
    cbar.ax.set_ylabel('Renewable ratio', rotation=270, labelpad=14)
    for spine in ['top','right']:
        ax.spines[spine].set_visible(False)
    fig.tight_layout()
    return svg_from_fig(fig)

def html_table(frame, index_name=None, classes='data-table'):
    f = frame.copy()
    if index_name:
        f.index.name = index_name
    return f.to_html(classes=classes, border=0, escape=False)

