wait_heat = df.pivot_table(index='location_type', columns='time_slot', values='waiting_time', aggfunc='mean').loc[loc_order, time_order]
queue_heat = df.pivot_table(index='traffic_density', columns='time_slot', values='waiting_time', aggfunc='mean').reindex(columns=time_order)
renew_heat = df.pivot_table(index='weather_condition', columns='time_slot', values='renewable_energy_ratio', aggfunc='mean').loc[weather_order, time_order]
