def fmt(value, decimals=1, suffix=''):
    if pd.isna(value):
        return 'n/a'
    if abs(value) >= 1000 and decimals == 0:
        return f'{value:,.0f}{suffix}'
    return f'{value:,.{decimals}f}{suffix}'

