def svg_from_fig(fig):
    buf = io.StringIO()
    fig.savefig(buf, format='svg', bbox_inches='tight')
    plt.close(fig)
    svg = buf.getvalue()
    start = svg.find('<svg')
    return svg[start:]

def heatmap_svg(pivot, title, cbar_label, cmap='YlOrRd', fmt_text='.1f'):
    fig, ax = plt.subplots(figsize=(7.4, 3.3))
    data = pivot.values.astype(float)
    im = ax.imshow(data, cmap=cmap, aspect='auto')
    ax.set_xticks(np.arange(len(pivot.columns)), labels=pivot.columns)
    ax.set_yticks(np.arange(len(pivot.index)), labels=pivot.index)
    ax.set_title(title, loc='left', fontweight='bold', color=palette['ink'])
    ax.tick_params(length=0)
    for spine in ax.spines.values():
        spine.set_visible(False)
    threshold = np.nanmean(data)
    for i in range(data.shape[0]):
        for j in range(data.shape[1]):
            val = data[i, j]
            color = 'white' if val > threshold else '#172033'
            ax.text(j, i, format(val, fmt_text), ha='center', va='center', color=color, fontweight='bold')
    cbar = fig.colorbar(im, ax=ax, fraction=0.046, pad=0.04)
    cbar.ax.set_ylabel(cbar_label, rotation=270, labelpad=14)
    fig.tight_layout()
    return svg_from_fig(fig)

def grouped_bar_svg(data, title, ylabel, colors=None):
    fig, ax = plt.subplots(figsize=(7.4, 3.6))
    data.plot(kind='bar', ax=ax, color=colors or [palette['sky'], palette['orange'], palette['green']], width=0.72)
    ax.set_title(title, loc='left', fontweight='bold', color=palette['ink'])
    ax.set_ylabel(ylabel)
    ax.set_xlabel('')
    ax.grid(axis='y', alpha=.25)
    ax.legend(frameon=False, loc='best')
    for spine in ['top','right','left']:
        ax.spines[spine].set_visible(False)
    fig.tight_layout()
    return svg_from_fig(fig)

def horizontal_bar_svg(series, title, xlabel, color=palette['blue']):
    fig, ax = plt.subplots(figsize=(7.4, 4.1))
    series = series.sort_values(ascending=True)
    bars = ax.barh(series.index.astype(str), series.values, color=color)
    ax.set_title(title, loc='left', fontweight='bold', color=palette['ink'])
    ax.set_xlabel(xlabel)
    ax.grid(axis='x', alpha=.25)
    for spine in ['top','right','left']:
        ax.spines[spine].set_visible(False)
    ax.tick_params(axis='y', length=0)
    for bar in bars:
        width = bar.get_width()
        ax.text(width, bar.get_y()+bar.get_height()/2, f' {width:.1f}', va='center', fontsize=8)
    fig.tight_layout()
