def scatter_svg(x, y, c, title, xlabel, ylabel):
    fig, ax = plt.subplots(figsize=(7.4, 3.8))
    sc = ax.scatter(x, y, c=c, cmap='viridis', s=18, alpha=.55, edgecolors='none')
    coef = np.polyfit(x, y, 1)
    xs = np.linspace(np.nanmin(x), np.nanmax(x), 100)
    ax.plot(xs, coef[0]*xs + coef[1], color=palette['red'], linewidth=2, label='linear fit')
    ax.set_title(title, loc='left', fontweight='bold', color=palette['ink'])
    ax.set_xlabel(xlabel)
